-- Más variedad de juegos en los drops.
-- 1) "Juego del día": una misión diaria por drop que cambia de formato cada día
--    (emoji-tema → verdadero o falso → completá el título → …). El formato del día sale de
--    rules.rounds, rotando por días desde el 1/1/2026 (hora de Buenos Aires).
-- 2) Juegos de ordenar (línea de tiempo / tracklist) con nombres reales en vez de "Fragmento 1..4".

CREATE OR REPLACE FUNCTION public.drop_round_questions(p_rules jsonb, p_period text)
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path TO 'public' AS $$
  WITH src AS (
    SELECT CASE WHEN p_rules ? 'rounds' THEN
      p_rules->'rounds'->(CASE WHEN p_period ~ '^\d{4}-\d{2}-\d{2}$'
        THEN ((p_period::date - date '2026-01-01') % jsonb_array_length(p_rules->'rounds') + jsonb_array_length(p_rules->'rounds')) % jsonb_array_length(p_rules->'rounds')
        ELSE 0 END)
    ELSE p_rules END AS r
  )
  SELECT CASE WHEN src.r ? 'pool' THEN (
    SELECT coalesce(jsonb_agg(CASE WHEN src.r ? 'format' THEN x.q || jsonb_build_object('format', src.r->>'format') ELSE x.q END ORDER BY md5(p_period || ':' || x.i::text)), '[]'::jsonb) FROM (
      SELECT q, i FROM jsonb_array_elements(src.r->'pool') WITH ORDINALITY t(q, i)
      ORDER BY md5(p_period || ':' || i::text) LIMIT coalesce((src.r->>'per_round')::int, 5)
    ) x)
  ELSE src.r->'questions' END FROM src;
$$;

